const ticket = $input.first().json;
const now = new Date();
const created = new Date(ticket.created_at);

const totalElapsedMinutes = Math.max(1, Math.floor((now - created) / 60000));

let businessMinutes = 0;
let cur = new Date(created.getTime());
while (cur < now) {
  const day = cur.getDay();
  const hour = cur.getHours();
  if (day >= 1 && day <= 5 && hour >= 8 && hour < 18) {
    businessMinutes += 1;
  }
  cur = new Date(cur.getTime() + 60000);
}
if (businessMinutes === 0) businessMinutes = totalElapsedMinutes;

const slaMinutes = ticket.sla_resolution_minutes || 1440;
const percentUsed = Math.round((totalElapsedMinutes / slaMinutes) * 100);

let alertLevel = 0;
let alertLevelName = 'AN TOÀN (<50%)';

if (percentUsed > 150) {
  alertLevel = 4;
  alertLevelName = 'NGHIÊM TRỌNG (>150%)';
} else if (percentUsed >= 100) {
  alertLevel = 3;
  alertLevelName = 'QUÁ HẠN (100-150%)';
} else if (percentUsed >= 80) {
  alertLevel = 2;
  alertLevelName = 'CẢNH BÁO CAO (80-100%)';
} else if (percentUsed >= 50) {
  alertLevel = 1;
  alertLevelName = 'THEO DÕI (50-80%)';
}

const lastLevel = ticket.last_alert_level || 0;
const shouldAlert = alertLevel >= 2 && alertLevel > lastLevel;

const newPromisedDate = new Date(now.getTime() + 4 * 3600000);
const newPromisedStr = newPromisedDate.toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' }) + ' ngày ' + newPromisedDate.toLocaleDateString('vi-VN');

return [{
  json: {
    ...ticket,
    elapsed_minutes: totalElapsedMinutes,
    business_minutes: businessMinutes,
    percent_used: percentUsed,
    current_alert_level: alertLevel,
    alert_level_name: alertLevelName,
    should_alert: shouldAlert,
    new_promised_at: newPromisedStr
  }
}];

