const allTickets = $('MySQL - Lấy ticket chưa đóng & luật SLA').all().map(i => i.json);

let total = allTickets.length;
let safeCount = 0;
let warning80 = 0;
let breached100 = 0;
let critical150 = 0;
let details = [];

const now = new Date();

allTickets.forEach(t => {
  const elapsed = Math.max(1, Math.floor((now - new Date(t.created_at)) / 60000));
  const sla = t.sla_resolution_minutes || 1440;
  const pct = Math.round((elapsed / sla) * 100);

  if (pct > 150) critical150++;
  else if (pct >= 100) breached100++;
  else if (pct >= 80) warning80++;
  else safeCount++;

  details.push({
    ticket_code: t.ticket_code,
    priority: t.priority,
    percent_used: pct + '%',
    assignee: t.assignee_name || 'Chưa gán',
    status: t.status
  });
});

return [{
  json: {
    total_tickets: total,
    safe_count: safeCount,
    warning_80_count: warning80,
    breached_100_count: breached100,
    critical_150_count: critical150,
    sla_compliance_rate: total > 0 ? Math.round(((total - (breached100 + critical150)) / total) * 100) : 100,
    details: details
  }
}];

